'use strict';
// Keep the legacy storage key and core namespace so existing records and backups remain compatible.
const F=Folio,KEY='folio-data-v1',$=s=>document.querySelector(s);
const paths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1z"/><path d="M9 21v-8h6v8"/>',transactions:'<path d="M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4"/>',investments:'<rect x="3" y="13" width="4" height="8" rx="1"/><rect x="10" y="8" width="4" height="13" rx="1"/><rect x="17" y="3" width="4" height="18" rx="1"/>',budgets:'<path d="M21 12a9 9 0 1 1-9-9v9z"/><path d="M15 3.5A8 8 0 0 1 20.5 9H15z"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3" fill="var(--surface)"/><circle cx="16" cy="17" r="3" fill="var(--surface)"/>',eye:'<path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7S2 12 2 12"/><circle cx="12" cy="12" r="3"/>',eyeOff:'<path d="m3 3 18 18M10 5h2c7 0 10 7 10 7a15 15 0 0 1-3 4M6 6a16 16 0 0 0-4 6s3 7 10 7a11 11 0 0 0 5-1"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',up:'<path d="m7 17 10-10M7 7h10v10"/>',down:'<path d="m7 7 10 10M7 17h10V7"/>',food:'<path d="M4 3v6a3 3 0 0 0 6 0V3M7 3v18M20 21V3c-5 0-5 10 0 10"/>',shopping:'<path d="M4 7h16l-1 14H5z"/><path d="M8 7V5a4 4 0 0 1 8 0v2"/>',transport:'<rect x="4" y="4" width="16" height="13" rx="4"/><path d="M4 10h16M7 17v3M17 17v3M7 13h1m8 0h1"/>',bills:'<path d="M5 3h14v18l-4-2-3 2-3-2-4 2zM8 7h8M8 11h8M8 15h4"/>',entertainment:'<rect x="3" y="6" width="18" height="15" rx="2"/><path d="m8 2 4 4 4-4m-6 5 6 3-6 3z"/>',health:'<path d="M9 3h6v6h6v6h-6v6H9v-6H3V9h6z"/>',education:'<path d="m2 8 10-5 10 5-10 5zM6 10v7c3 3 9 3 12 0v-7M22 8v8"/>',other:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 12h.01M12 12h.01M16 12h.01"/>',wallet:'<path d="M20 7H5a2 2 0 0 1 0-4h13v4M4 5v14a2 2 0 0 0 2 2h14V7"/><path d="M20 11h-6v6h6m-3-3h.01"/>',edit:'<path d="m14 5 5 5M4 20l5-1L21 7a2 2 0 0 0-5-5L4 14z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',leaf:'<path d="M20 3C8 2 1 10 7 17s15-2 13-14ZM5 21 16 10"/>'};
const icon=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(paths[n]||paths.other)+'</svg>';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const colors={'Food & drinks':'var(--chart-emerald)',Shopping:'var(--chart-blue)',Transport:'var(--chart-teal)','Bills & rent':'var(--chart-slate)',Entertainment:'var(--chart-pale)',Health:'var(--chart-teal)',Education:'var(--chart-blue)',Other:'var(--chart-slate)',Salary:'var(--chart-emerald)',Freelance:'var(--chart-blue)',Gift:'var(--chart-pale)',Stocks:'var(--chart-emerald)','Mutual funds':'var(--chart-blue)',Gold:'var(--chart-gold)',Crypto:'var(--chart-pale)','Fixed income':'var(--chart-slate)'};
const catIcons={'Food & drinks':'food',Shopping:'shopping',Transport:'transport','Bills & rent':'bills',Entertainment:'entertainment',Health:'health',Education:'education',Salary:'wallet',Freelance:'wallet'};
let state,loadError=false;
try{const raw=localStorage.getItem(KEY);state=raw?F.validate(JSON.parse(raw)):F.sample();}catch{state=F.emptyState();loadError=true;}
let month=F.dateString().slice(0,7),view='overview',chartMode='month',hidden=false,search='',typeFilter='all',categoryFilter='all',toastTimer;
const money=(n,digits=0)=>new Intl.NumberFormat(state.settings.currency==='INR'?'en-IN':'en-US',{style:'currency',currency:state.settings.currency,minimumFractionDigits:digits,maximumFractionDigits:digits}).format(n);
const amountHtml=n=>{const str=money(n,2),index=str.lastIndexOf('.');return index<0?esc(str):esc(str.slice(0,index))+'<span class="decimal">'+esc(str.slice(index))+'</span>';};
const monthName=()=>new Date(month+'-01T12:00:00').toLocaleDateString('en-GB',{month:'long',year:'numeric'});
const shortDate=d=>new Date(d+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short'});
const uid=()=>crypto.randomUUID();
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300);}
function persist(next){try{F.validate(next);localStorage.setItem(KEY,JSON.stringify(next));state=next;return true;}catch(e){toast('Could not save: '+e.message);return false;}}
function change(fn,message){const next=JSON.parse(JSON.stringify(state));fn(next);if(persist(next)){render();if(message)toast(message);return true;}return false;}
function empty(title,description,action,label){return '<div class="empty-state">'+icon('leaf')+'<h3>'+title+'</h3><p>'+description+'</p>'+(action?'<button class="button primary" data-action="'+action+'">'+label+'</button>':'')+'</div>';}
const navs=[['overview','Home','home'],['investments','Portfolio','investments'],['budgets','Budgets','wallet'],['transactions','History','transactions'],['settings','Settings','settings']];
function renderNav(){for(const id of ['desktop-nav','mobile-nav'])$('#'+id).innerHTML=navs.map(([v,l,i])=>'<button data-view="'+v+'" aria-label="'+l+'" '+(v===view?'aria-current="page"':'')+' class="'+(v===view?'active':'')+'">'+icon(i)+'<span>'+l+'</span>'+(v===view&&id==='desktop-nav'?'<span class="nav-active-dot"></span>':'')+'</button>').join('');}
function go(v){if(!navs.some(n=>n[0]===v))v='overview';view=v;location.hash=v;render();window.scrollTo({top:0,behavior:'instant'});}
function stat(label,value,note,cls=''){return '<div class="panel stat-card"><div class="subtle">'+label+'</div><div class="money '+cls+'">'+amountHtml(value)+'</div><small>'+note+'</small></div>';}
function render(){
  document.body.setAttribute('data-view',view);
  document.body.setAttribute('data-demo',String(state.demo));
  renderNav();const names={overview:['Your Complete Financial Vault','Track expenses, manage investments, and plan your spending from one organized dashboard.'],transactions:['Every transaction. In perspective.','Review your income and expenses, with the details that matter.'],investments:['Your portfolio, clearly defined','Understand your allocation, track your holdings, and measure your progress.'],budgets:['A plan for every priority','Set clear spending limits and stay informed throughout the month.'],settings:['Your vault. Your preferences.','Manage your profile, keep a backup, and make DaddyVault your own.']};
  $('#page-title').innerHTML=esc(names[view][0]);$('#page-description').textContent=names[view][1];$('#breadcrumb').textContent=navs.find(n=>n[0]===view)[1];$('#month-filter').value=month;$('#month-filter').hidden=['settings','investments'].includes(view);
  $('#demo-banner').hidden=!state.demo;$('#demo-banner').style.display=state.demo?'flex':'none';
  document.querySelector('.profile strong').textContent=state.settings.name;
  $('#profile-name').textContent=state.settings.name;
  const initials=state.settings.name.split(/\s+/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase()||'ME';
  document.querySelectorAll('.avatar').forEach(a=>a.textContent=initials);
  $('#privacy-toggle').innerHTML=icon(hidden?'eyeOff':'eye');$('#privacy-toggle').setAttribute('aria-label',hidden?'Show balances':'Hide balances');$('#privacy-toggle').setAttribute('title',hidden?'Show balances':'Hide balances');$('#privacy-toggle').setAttribute('aria-pressed',String(hidden));
  const action=$('.heading-actions .button');action.dataset.action=view==='investments'?'add-holding':view==='budgets'?'add-budget':'add-transaction';action.innerHTML='<span>＋</span> '+(view==='investments'?'Add investment':view==='budgets'?'Set budget':'Add transaction');action.hidden=view==='settings';action.style.display=view==='settings'?'none':'inline-flex';
  $('#content').innerHTML=({overview:overview,transactions:transactions,investments:investments,budgets:budgets,settings:settings})[view]();
}
function flowSymbol(expense=false){return '<div class="flow-symbol '+(expense?'coral':'green')+'" aria-hidden="true">'+icon(expense?'up':'down')+'</div>';}
function dotSpark(type){
  const rows=F.summary(state,month).rows.filter(t=>t.type===type),days=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();
  const values=Array.from({length:24},(_,i)=>rows.filter(t=>Math.min(23,Math.floor((Number(t.date.slice(8))-1)/days*24))===i).reduce((s,t)=>s+t.amount,0)),max=Math.max(1,...values);
  return '<div class="dot-spark '+(type==='income'?'spark-in':'spark-out')+'" role="img" aria-label="'+type+' distribution for '+monthName()+'">'+values.map(v=>'<i style="--level:'+Math.max(5,Math.round(v/max*100))+'%" class="'+(v?'has-value':'')+'"></i>').join('')+'</div>';
}
function overview(){
  const s=F.summary(state,month);
  return '<div class="vault-layout"><div class="home-column"><article class="panel balance-card"><div class="card-label">Available balance <button class="card-eye" data-action="toggle-privacy" aria-label="'+(hidden?'Show':'Hide')+' balances">'+icon(hidden?'eyeOff':'eye')+'</button></div><div class="money '+(s.cash<0?'coral':'')+'">'+amountHtml(s.cash)+'</div><div class="chip-mark" aria-hidden="true"><svg viewBox="0 0 32 26"><rect x="1" y="1" width="30" height="24" rx="5"/><path d="M11 1v7H1m30 0H21V1M11 25v-7H1m30 0H21v7M11 8h10v10H11z"/></svg></div><div class="card-bottom"><div><span>Account holder</span><strong>'+esc(state.settings.name.toUpperCase())+'</strong></div><div class="card-brand"><span>PERSONAL VAULT</span><strong>DADDYVAULT</strong></div></div></article><div class="quick-actions"><button class="button primary" data-action="add-income"><span>+</span> Add income</button><button class="button" data-action="add-transaction">'+icon('up')+' Expense</button><button class="button" data-view="investments">'+icon('investments')+' Invest</button></div><div class="month-caption">'+monthName()+'</div><div class="cash-stats"><article class="panel cash-card"><div class="label">Money in</div><div class="cash-amount financial"><span class="green">↗</span> '+money(s.income,2)+'</div>'+dotSpark('income')+'</article><article class="panel cash-card"><div class="label">Money spent</div><div class="cash-amount financial"><span class="coral">↘</span> '+money(s.expense,2)+'</div>'+dotSpark('expense')+'</article></div><article class="transactions-panel"><div class="panel-header"><h3>Recent activity</h3><button class="text-button" data-view="transactions">See all</button></div>'+recentRows(s.rows)+'</article></div><div class="insights-column">'+chart()+allocationStrips()+'<article class="budget-panel"><div class="panel-header"><h3>Monthly budgets</h3><button class="text-button" data-view="budgets">See all</button></div>'+state.budgets.slice(0,3).map(b=>budgetMini(b)).join('')+(state.budgets.length?'':empty('Make a little room','Set a monthly limit for a spending category.','add-budget','Set a budget'))+'</article></div></div>';
}
function allocationStrips(){
  const total=F.summary(state,month).value;
  const alloc=F.assets.map(a=>({name:a,value:state.holdings.filter(h=>h.asset===a).reduce((s,h)=>s+h.units*h.price,0)})).filter(a=>a.value>0).sort((a,b)=>b.value-a.value);
  const groups=alloc.length>3?[...alloc.slice(0,2),{name:'Other holdings',value:alloc.slice(2).reduce((s,a)=>s+a.value,0)}]:alloc;
  return '<section class="allocation-strips"><div class="panel-header"><h3>Portfolio allocation</h3><button class="text-button" data-view="investments">'+icon('arrow')+'</button></div><div class="strip-grid">'+(groups.length?groups.map((a,i)=>'<div class="strip" style="--strip-color:'+['#bf756b','#63bfb4','#70aeb6'][i]+'"><strong>'+(a.value/total*100).toFixed(0)+'%</strong><div class="strip-bars" style="--fill:'+(a.value/total*100)+'%"></div><small>'+a.name+'</small></div>').join(''):'<p class="subtle">Add an investment to see your allocation.</p>')+'</div></section>';
}
function chart(){
  const rows=F.summary(state,month).rows.filter(t=>t.type==='expense');let buckets,caption;
  if(chartMode==='week'){
    const now=F.dateString(),days=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate(),end=month===now.slice(0,7)?Number(now.slice(8)):days,start=Math.max(1,end-6);
    buckets=Array.from({length:end-start+1},(_,i)=>{const day=start+i,date=month+'-'+String(day).padStart(2,'0');return {label:new Date(date+'T12:00:00').toLocaleDateString('en',{weekday:'short'}),rows:rows.filter(t=>t.date===date)};});caption=start+'–'+end+' '+monthName();
  }else{buckets=Array.from({length:5},(_,i)=>({label:['1–7','8–14','15–21','22–28','29–31'][i],rows:rows.filter(t=>Math.min(4,Math.floor((Number(t.date.slice(8))-1)/7))===i)}));caption=monthName();}
  const sums=buckets.map(b=>b.rows.reduce((s,t)=>s+t.amount,0)),max=Math.max(1,...sums),total=sums.reduce((a,b)=>a+b,0),active=Math.max(0,sums.lastIndexOf(Math.max(...sums))),used=F.categories.filter(c=>buckets.some(b=>b.rows.some(t=>t.category===c)));
  return '<article class="chart-panel"><div class="panel-header"><h3 class="expense-label">Expenses '+icon('down')+'</h3><div class="segmented"><button data-chart="week" aria-pressed="'+(chartMode==='week')+'" class="'+(chartMode==='week'?'active':'')+'">Last 7 days</button><button data-chart="month" aria-pressed="'+(chartMode==='month')+'" class="'+(chartMode==='month'?'active':'')+'">Month</button></div></div><div class="subtle">Spent</div><div class="chart-total money">'+amountHtml(total)+'</div><div class="chart-period">'+caption+'</div><div class="bar-chart" role="img" aria-label="Spending by period: '+esc(buckets.map((b,i)=>b.label+': '+money(sums[i])).join(', '))+'"><div class="bar-area">'+buckets.map((b,i)=>'<div class="bar-group '+(active===i?'highlight':'')+'" title="'+esc(b.label+': '+money(sums[i]))+'">'+F.categories.map(c=>{const val=b.rows.filter(t=>t.category===c).reduce((s,t)=>s+t.amount,0);return val?'<div class="bar-segment" style="height:'+val/max*83+'%;background:'+(i===active?colors[c]:'var(--chart-inactive)')+'"></div>':'';}).join('')+'<span class="bar-label">'+b.label+'</span></div>').join('')+'</div></div><div class="chart-legend">'+(used.length?used.map(c=>'<div><span><i class="legend-dot" style="background:'+colors[c]+'"></i>'+c+'</span><strong class="financial">'+money(buckets.flatMap(b=>b.rows).filter(t=>t.category===c).reduce((s,t)=>s+t.amount,0))+'</strong></div>').join(''):'No expenses recorded for this period.')+'</div></article>';
}
function recentRows(rows){
  if(!rows.length)return empty('Your activity starts here','Record income or an expense to build your financial picture.','add-transaction','Add transaction');
  return [...rows].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(t=>'<div class="transaction-row"><span class="category-icon">'+icon(catIcons[t.category]||'other')+'</span><div><div class="transaction-name">'+esc(t.name)+'</div><div class="transaction-meta">'+shortDate(t.date)+' · '+esc(t.account)+'</div></div><span class="category-badge"><i class="legend-dot" style="background:'+colors[t.category]+'"></i>'+esc(t.category)+'</span><div class="transaction-amount '+(t.type==='income'?'green':'coral')+'">'+(t.type==='income'?'+':'−')+money(t.amount)+'<small>'+ (t.type==='income'?'Received':'Paid')+'</small></div></div>').join('');
}
function portfolioCard(){
  const s=F.summary(state,month),alloc=F.assets.map(a=>({name:a,value:state.holdings.filter(h=>h.asset===a).reduce((sum,h)=>sum+h.units*h.price,0)})).filter(a=>a.value>0);let offset=0;
  const gradient=alloc.map(a=>{let start=offset;offset+=a.value/s.value*100;return colors[a.name]+' '+start+'% '+Math.max(start,offset-.9)+'%, var(--surface) '+Math.max(start,offset-.9)+'% '+offset+'%';}).join(',');
  return '<article class="panel portfolio-panel"><div class="panel-header"><h3>Investment portfolio</h3>'+icon('investments')+'</div><div class="subtle">Current value</div><div class="money portfolio-value">'+amountHtml(s.value)+'</div><div class="return-pill financial '+(s.gain<0?'coral':'')+'">'+(s.gain>=0?'+':'')+money(s.gain)+' ('+(s.gain>=0?'+':'')+s.returnPct.toFixed(2)+'%)</div><div class="donut-wrap" role="img" aria-label="Investment allocation: '+esc(alloc.length?alloc.map(a=>a.name+' '+(a.value/s.value*100).toFixed(1)+' percent').join(', '):'No holdings with a current value')+'"><div class="donut" style="background:'+(gradient?'conic-gradient('+gradient+')':'var(--chart-track)')+'"></div><div class="donut-center">'+state.holdings.length+'<small>holdings</small></div></div>'+alloc.map(a=>'<div class="allocation-row"><span><i class="legend-dot" style="background:'+colors[a.name]+'"></i>'+a.name+'</span><strong>'+(a.value/s.value*100).toFixed(1)+'%</strong></div>').join('')+'<button class="button portfolio-link" data-view="'+(view==='investments'?'overview':'investments')+'">'+(view==='investments'?'Back to overview':'Explore your investments')+' '+icon('arrow')+'</button><p class="overview-note">Manual values · no live market feed</p></article>';
}
function budgetMini(b){const spent=F.spending(state,month,b.category),pct=spent/b.limit*100;return '<div class="budget-item"><div class="budget-row"><span>'+esc(b.category)+'</span><small class="financial">'+money(spent)+' <span style="color:var(--muted)">/ '+money(b.limit)+'</span></small></div><div class="progress"><div style="width:'+Math.min(100,pct)+'%;background:'+(pct>100?'var(--negative)':colors[b.category])+'"></div></div></div>';}
function transactions(){
  const s=F.summary(state,month);
  return '<div class="stat-strip">'+stat('Income',s.income,'Recorded this month','green')+stat('Expenses',s.expense,'Recorded this month')+stat('Net cash flow',s.net,'Income minus expenses',s.net>=0?'green':'coral')+'</div><article class="panel panel-pad"><div class="toolbar"><input class="search-field" id="search" placeholder="Search transactions..." aria-label="Search transactions" value="'+esc(search)+'"><select id="type-filter" aria-label="Transaction type"><option value="all">All types</option><option value="expense" '+(typeFilter==='expense'?'selected':'')+'>Expenses</option><option value="income" '+(typeFilter==='income'?'selected':'')+'>Income</option></select><select id="category-filter" aria-label="Category"><option value="all">All categories</option>'+[...new Set([...F.categories,...F.incomeCategories])].map(c=>'<option '+(c===categoryFilter?'selected':'')+'>'+c+'</option>').join('')+'</select><button class="button ghost" data-action="export-csv">'+icon('download')+' Export</button></div><div id="transaction-results">'+transactionTable()+'</div></article>';
}
function filteredTransactions(){return F.summary(state,month).rows.filter(t=>(typeFilter==='all'||t.type===typeFilter)&&(categoryFilter==='all'||t.category===categoryFilter)&&[t.name,t.category,t.account].join(' ').toLowerCase().includes(search.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));}
function transactionTable(){const rows=filteredTransactions();return rows.length?'<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable financial records"><table class="transaction-table"><thead><tr><th>TRANSACTION</th><th>DATE</th><th>CATEGORY</th><th class="right">AMOUNT</th><th class="right">ACTIONS</th></tr></thead><tbody>'+rows.map(t=>'<tr><td><span class="table-name">'+esc(t.name)+'</span><small>'+esc(t.account)+' · '+t.type+'</small></td><td>'+shortDate(t.date)+'</td><td>'+esc(t.category)+'</td><td class="right financial '+(t.type==='income'?'green':'coral')+'">'+(t.type==='income'?'+':'−')+money(t.amount,2)+'</td><td class="right table-actions"><button class="icon-button" data-edit-transaction="'+esc(t.id)+'" aria-label="Edit '+esc(t.name)+'">'+icon('edit')+'</button><button class="icon-button" data-delete-transaction="'+esc(t.id)+'" aria-label="Delete '+esc(t.name)+'">'+icon('trash')+'</button></td></tr>').join('')+'</tbody></table></div><p class="notice">'+rows.length+' transactions · '+monthName()+'</p>':empty('No matching transactions','Try a different filter, or record a new transaction.','add-transaction','Add transaction');}
function investments(){
  const s=F.summary(state,month);return '<div class="stat-strip">'+stat('Total invested',s.cost,'Cost basis of current holdings')+stat('Current value',s.value,'Based on your latest entries')+stat('Unrealized return',s.gain,(s.gain>=0?'+':'')+s.returnPct.toFixed(2)+'% on cost',s.gain>=0?'green':'coral')+'</div><div class="holdings-grid"><article class="panel panel-pad"><div class="panel-header"><h3>Your holdings</h3><span class="help-tag">MANUALLY TRACKED</span></div>'+(state.holdings.length?'<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable financial records"><table class="holdings-table"><thead><tr><th>ASSET</th><th>UNITS / COST</th><th class="right">VALUE / RETURN</th><th class="right">ACTIONS</th></tr></thead><tbody>'+state.holdings.map(h=>{const gain=h.units*(h.price-h.cost);return '<tr><td><span class="holding-symbol">'+esc(h.symbol||h.name.slice(0,2).toUpperCase())+'</span><span class="table-name">'+esc(h.name)+'</span><small>'+h.asset+' · Updated '+shortDate(h.date)+'</small></td><td class="financial">'+h.units+' units<small>'+money(h.cost,2)+' / unit</small></td><td class="right financial">'+money(h.units*h.price,2)+'<small class="'+(gain>=0?'green':'coral')+'">'+(gain>=0?'+':'')+money(gain,2)+'</small></td><td class="right table-actions"><button class="icon-button" data-edit-holding="'+esc(h.id)+'" aria-label="Edit '+esc(h.name)+'">'+icon('edit')+'</button><button class="icon-button" data-delete-holding="'+esc(h.id)+'" aria-label="Delete '+esc(h.name)+'">'+icon('trash')+'</button></td></tr>';}).join('')+'</tbody></table></div>':empty('Build your investment overview','Add a stock, mutual fund, gold, or another holding.','add-holding','Add investment'))+'<p class="notice">Holdings are tracked separately from your cash balance. Update prices manually; adding a holding does not create a cash transaction. Values are in '+state.settings.currency+'.</p></article>'+portfolioCard()+'</div>';
}
function budgets(){
  const limit=state.budgets.reduce((s,b)=>s+b.limit,0),spent=state.budgets.reduce((s,b)=>s+F.spending(state,month,b.category),0);return '<div class="stat-strip">'+stat('Monthly plan',limit,'Across '+state.budgets.length+' categories')+stat('Spent in budgeted categories',spent,monthName())+stat('Budget remaining',limit-spent,limit-spent>=0?'Space to spend with intention':'You have gone over your plan',limit-spent>=0?'green':'coral')+'</div>'+(state.budgets.length?'<div class="budget-grid">'+state.budgets.map(b=>{const used=F.spending(state,month,b.category),remaining=b.limit-used,pct=used/b.limit*100;return '<article class="panel budget-large"><div class="panel-header"><div class="budget-icon" style="color:'+colors[b.category]+'">'+icon(catIcons[b.category]||'other')+'</div><div><button class="icon-button" data-edit-budget="'+esc(b.category)+'" aria-label="Edit '+esc(b.category)+' budget">'+icon('edit')+'</button> <button class="icon-button" data-delete-budget="'+esc(b.category)+'" aria-label="Delete '+esc(b.category)+' budget">'+icon('trash')+'</button></div></div><h3>'+b.category+'</h3><div class="money">'+amountHtml(used)+'</div><div class="subtle financial" style="margin-top:6px">of '+money(b.limit)+' monthly budget</div><div class="progress"><div style="width:'+Math.min(100,pct)+'%;background:'+(pct>100?'var(--negative)':colors[b.category])+'"></div></div><div class="budget-row"><span class="'+(pct>100?'coral':'subtle')+'">'+pct.toFixed(0)+'% used</span><small class="financial '+(remaining<0?'coral':'')+'">'+money(Math.abs(remaining))+' '+(remaining<0?'over budget':'left')+'</small></div></article>';}).join('')+'</div><p class="notice">These category limits repeat each month. Spending is calculated from expenses in the selected month.</p>':'<article class="panel">'+empty('Plan your monthly spending','Set a monthly limit for the things you spend on most.','add-budget','Create your first budget')+'</article>');
}
function settings(){return '<div class="settings-grid"><article class="panel"><h3>Profile & preferences</h3><p>Personalize your DaddyVault workspace.</p><form id="settings-form"><label>Your name<input name="name" value="'+esc(state.settings.name)+'" required maxlength="60"></label><label>Display currency<select name="currency">'+['INR','USD','EUR','GBP'].map(c=>'<option '+(state.settings.currency===c?'selected':'')+'>'+c+'</option>').join('')+'</select></label><label>Opening cash balance<input name="openingBalance" type="number" step=".01" min="-1000000000" max="1000000000" value="'+state.settings.openingBalance+'" required></label><p class="form-note">Currency changes labels only, not amounts. Your available balance is the opening balance plus recorded income minus expenses through today.</p><button class="button primary" type="submit">Save preferences</button></form></article><article class="panel"><h3>Data & backups</h3><p>Records are saved in this browser on this device. There is no bank connection, account login, cloud sync, or live investment feed.</p><h3 style="margin-top:28px">Keep a copy</h3><p>Download a JSON backup of all your records and settings. Restore it here, or in another browser, whenever you need.</p><div class="settings-actions"><button class="button" data-action="backup">'+icon('download')+' Download backup</button><button class="button ghost" data-action="restore">Restore backup</button><input type="file" id="import-file" accept=".json,application/json" hidden></div><div class="settings-note">Clearing browser data also removes your records. Keep a backup.</div></article><article class="panel full danger-zone"><h3>Reset workspace</h3><p>Remove the current transactions, holdings, and budgets and begin with an empty account. Export a backup first if you want to keep anything.</p><div class="settings-actions"><button class="button danger" data-action="start-fresh">Clear data & start fresh</button><button class="button ghost" data-action="load-demo">Load sample data</button></div></article></div>';}
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function options(values,selected){return values.map(v=>'<option '+(v===selected?'selected':'')+'>'+esc(v)+'</option>').join('');}
function transactionForm(id,initialType='expense'){
  const t=state.transactions.find(t=>t.id===id)||{type:initialType,name:'',amount:'',category:initialType==='income'?'Salary':'Food & drinks',date:F.dateString(),account:'UPI'};
  openModal(id?'Edit transaction':'Add transaction','<form id="transaction-form" data-id="'+esc(id||'')+'"><div class="form-row"><label>Type<select name="type" id="entry-type">'+options(['expense','income'],t.type)+'</select></label><label>Amount ('+state.settings.currency+')<input name="amount" type="number" min="0.01" max="1000000000" step=".01" placeholder="0.00" value="'+t.amount+'" required autofocus></label></div><label>Description<input name="name" placeholder="e.g. Coffee with friends" value="'+esc(t.name)+'" maxlength="100" required></label><div class="form-row"><label>Category<select name="category" id="entry-category">'+options(t.type==='expense'?F.categories:F.incomeCategories,t.category)+'</select></label><label>Date<input name="date" type="date" value="'+t.date+'" max="'+F.dateString()+'" required></label></div><label>Paid through / received in<select name="account">'+options(['UPI','Card','Cash','Bank'],t.account)+'</select></label><button class="button primary" type="submit">'+(id?'Save changes':'Add transaction')+'</button></form>');
}
function holdingForm(id){
  const h=state.holdings.find(h=>h.id===id)||{name:'',symbol:'',asset:'Mutual funds',units:'',cost:'',price:'',date:F.dateString()};
  openModal(id?'Update investment':'Add investment','<form id="holding-form" data-id="'+esc(id||'')+'"><label>Investment name<input name="name" maxlength="100" placeholder="e.g. Nifty 50 Index Fund" value="'+esc(h.name)+'" required autofocus></label><div class="form-row"><label>Asset type<select name="asset">'+options(F.assets,h.asset)+'</select></label><label>Symbol (optional)<input name="symbol" maxlength="12" placeholder="NIFTY50" value="'+esc(h.symbol)+'"></label></div><div class="form-row"><label>Units held<input name="units" type="number" min="0.00000001" max="1000000000" step="any" value="'+h.units+'" required></label><label>Average cost / unit<input name="cost" type="number" min="0" max="1000000000" step="any" value="'+h.cost+'" required></label></div><div class="form-row"><label>Current price / unit<input name="price" type="number" min="0" max="1000000000" step="any" value="'+h.price+'" required></label><label>Valuation date<input name="date" type="date" value="'+h.date+'" max="'+F.dateString()+'" required></label></div><p class="form-note">Enter all prices in '+state.settings.currency+'. For a fixed deposit, use 1 unit and the total invested / current value. This will not change your cash balance.</p><button class="button primary" type="submit">'+(id?'Update holding':'Add investment')+'</button></form>');
}
function budgetForm(category){
  const b=state.budgets.find(b=>b.category===category);const available=b?[category]:F.categories.filter(c=>!state.budgets.some(b=>b.category===c));
  if(!available.length){toast('All categories already have a budget. Edit an existing one.');return;}
  openModal(b?'Edit monthly budget':'Create a monthly budget','<form id="budget-form"><label>Category<select name="category">'+options(available,category)+'</select></label><label>Monthly limit ('+state.settings.currency+')<input name="limit" type="number" min=".01" max="1000000000" step=".01" value="'+(b?b.limit:'')+'" placeholder="0.00" required autofocus></label><p class="form-note">This limit repeats every month. Your recorded expenses automatically count toward it.</p><button class="button primary" type="submit">Save budget</button></form>');
}
function confirmAction(title,description,label,fn){openModal(title,'<p class="confirm-text">'+description+'</p><div class="confirm-actions"><button class="button ghost" id="confirm-cancel">Cancel</button><button class="button danger" id="confirm-go">'+label+'</button></div>');$('#confirm-cancel').onclick=closeModal;$('#confirm-go').onclick=()=>{closeModal();fn();};}
function download(name,data,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportCSV(){const cell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const rows=filteredTransactions();download('daddyvault-transactions-'+month+'.csv',[['Date','Description','Type','Category','Account','Amount','Currency'],...rows.map(t=>[t.date,t.name,t.type,t.category,t.account,t.amount,state.settings.currency])].map(r=>r.map(cell).join(',')).join('\r\n'),'text/csv;charset=utf-8');toast('Transaction export downloaded');}
document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.view){go(b.dataset.view);return;}if(b.dataset.chart){chartMode=b.dataset.chart;render();return;}
  if(b.dataset.editTransaction){transactionForm(b.dataset.editTransaction);return;}if(b.dataset.editHolding){holdingForm(b.dataset.editHolding);return;}if(b.dataset.editBudget){budgetForm(b.dataset.editBudget);return;}
  for(const [key,field,label] of [['deleteTransaction','transactions','transaction'],['deleteHolding','holdings','holding'],['deleteBudget','budgets','budget']])if(b.dataset[key]){const id=b.dataset[key];confirmAction('Delete this '+label+'?','This removes the '+label+' from your records. Your totals will be updated.','Delete '+label,()=>change(s=>{s[field]=s[field].filter(x=>(field==='budgets'?x.category:x.id)!==id);},'Removed from your records'));return;}
  const action=b.dataset.action;
  if(action==='add-income')transactionForm(undefined,'income');
  if(action==='toggle-privacy')$('#privacy-toggle').onclick();
  if(action==='add-transaction')transactionForm();if(action==='add-holding')holdingForm();if(action==='add-budget')budgetForm();
  if(action==='export-csv')exportCSV();
  if(action==='backup'){download('daddyvault-backup-'+F.dateString()+'.json',JSON.stringify(state,null,2),'application/json');toast('Backup downloaded');}
  if(action==='restore')$('#import-file').click();
  if(action==='start-fresh')confirmAction('Start a new workspace?','This removes all current transactions, holdings, and budgets. Your name and currency stay; the opening balance resets to zero. Download a backup in Settings first if you need one.','Start fresh',()=>{if(persist(F.emptyState({...state.settings,openingBalance:0}))){go('overview');toast('Your DaddyVault is ready. Add your first transaction.');}});
  if(action==='load-demo')confirmAction('Explore sample data?','This replaces your current records with fictional examples. Download a backup first to keep your records.','Load examples',()=>{if(persist(F.sample())){month=F.dateString().slice(0,7);go('overview');toast('Sample data loaded');}});
});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#transaction-results').innerHTML=transactionTable();}});
document.addEventListener('change',async e=>{
  if(e.target.id==='month-filter'){if(/^\d{4}-\d{2}$/.test(e.target.value)){month=e.target.value;render();}}
  if(e.target.id==='type-filter'){typeFilter=e.target.value;$('#transaction-results').innerHTML=transactionTable();}
  if(e.target.id==='category-filter'){categoryFilter=e.target.value;$('#transaction-results').innerHTML=transactionTable();}
  if(e.target.id==='entry-type')$('#entry-category').innerHTML=options(e.target.value==='expense'?F.categories:F.incomeCategories);
  if(e.target.id==='import-file'){
    const file=e.target.files[0];if(!file)return;
    try{if(file.size>10000000)throw Error('Backup is too large.');const imported=F.validate(JSON.parse(await file.text()));confirmAction('Restore this backup?','Replace your current records with '+imported.transactions.length+' transactions, '+imported.holdings.length+' holdings and '+imported.budgets.length+' budgets from this backup.','Restore backup',()=>{if(persist(imported)){render();toast('Backup restored');}});}catch(err){toast('Could not import: '+err.message);}finally{e.target.value='';}
  }
});
document.addEventListener('submit',e=>{
  const form=e.target;if(!['transaction-form','holding-form','budget-form','settings-form'].includes(form.id))return;e.preventDefault();const data=Object.fromEntries(new FormData(form));let success=false;
  if(form.id==='transaction-form'){const t={...data,id:form.dataset.id||uid(),name:data.name.trim(),amount:F.round(Number(data.amount))};if(!t.name){toast('Enter a description.');return;}if(t.date>F.dateString()){toast('Choose today or an earlier date.');return;}success=change(s=>{const i=s.transactions.findIndex(x=>x.id===t.id);if(i>=0)s.transactions[i]=t;else s.transactions.push(t);},'Transaction saved');}
  if(form.id==='holding-form'){const h={...data,id:form.dataset.id||uid(),name:data.name.trim(),symbol:data.symbol.trim().toUpperCase(),units:Number(data.units),cost:Number(data.cost),price:Number(data.price)};if(!h.name){toast('Enter an investment name.');return;}if(h.date>F.dateString()){toast('Choose today or an earlier date.');return;}success=change(s=>{const i=s.holdings.findIndex(x=>x.id===h.id);if(i>=0)s.holdings[i]=h;else s.holdings.push(h);},'Investment saved');}
  if(form.id==='budget-form'){success=change(s=>{const b={category:data.category,limit:F.round(Number(data.limit))},i=s.budgets.findIndex(x=>x.category===b.category);if(i>=0)s.budgets[i]=b;else s.budgets.push(b);},'Monthly budget saved');}
  if(form.id==='settings-form'){if(!data.name.trim()){toast('Please enter your name.');return;}change(s=>{s.settings={name:data.name.trim(),currency:data.currency,openingBalance:F.round(Number(data.openingBalance))};},'Preferences saved');return;}
  if(success)closeModal();
});
$('#close-modal').onclick=closeModal;
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeModal();}});
$('#privacy-toggle').onclick=()=>{hidden=!hidden;document.body.classList.toggle('privacy-hidden',hidden);render();};
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(navs.some(n=>n[0]===hash)){view=hash;render();}});
view=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'overview';render();
if(loadError)toast('Saved data could not be loaded. Existing storage has not been overwritten.');
